PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE users (
	id INTEGER NOT NULL, 
	username VARCHAR NOT NULL, 
	password_hash VARCHAR NOT NULL, 
	full_name VARCHAR NOT NULL, 
	role VARCHAR, 
	is_active BOOLEAN, 
	created_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE vehicles (
	id INTEGER NOT NULL, 
	plate_number VARCHAR NOT NULL, 
	trailer_number VARCHAR, 
	vehicle_type VARCHAR, 
	brand VARCHAR, 
	model VARCHAR, 
	year INTEGER, 
	payload_capacity FLOAT, 
	status VARCHAR, 
	registration_expiry DATE, 
	insurance_expiry DATE, 
	badge_expiry DATE, 
	gdd_head_expiry DATE, 
	gdd_trailer_expiry DATE, 
	oil_interval_km FLOAT, 
	oil_last_km FLOAT, 
	oil_last_date DATE, 
	current_odometer FLOAT, 
	notes TEXT, 
	created_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE barges (
	id INTEGER NOT NULL, 
	name VARCHAR NOT NULL, 
	registration_number VARCHAR, 
	payload_capacity FLOAT, 
	ownership_type VARCHAR, 
	owner_name VARCHAR, 
	owner_phone VARCHAR, 
	rental_price_per_day FLOAT, 
	status VARCHAR, 
	notes TEXT, 
	created_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE drivers (
	id INTEGER NOT NULL, 
	full_name VARCHAR NOT NULL, 
	phone VARCHAR, 
	address VARCHAR, 
	national_id VARCHAR, 
	national_id_expiry DATE, 
	license_number VARCHAR, 
	license_class VARCHAR, 
	license_expiry DATE, 
	vehicle_id INTEGER, 
	status VARCHAR, 
	notes TEXT, 
	created_at DATETIME, rating_score FLOAT DEFAULT 95.0, fuel_saving_score FLOAT DEFAULT 94.0, safety_score FLOAT DEFAULT 98.0, total_trips INTEGER DEFAULT 0, 
	PRIMARY KEY (id), 
	FOREIGN KEY(vehicle_id) REFERENCES vehicles (id)
);
CREATE TABLE fuel_records (
	id INTEGER NOT NULL, 
	record_date DATE NOT NULL, 
	vehicle_id INTEGER NOT NULL, 
	liters FLOAT NOT NULL, 
	price_per_liter FLOAT NOT NULL, 
	total_cost FLOAT NOT NULL, 
	station_name VARCHAR, 
	odometer FLOAT, 
	notes TEXT, 
	created_by INTEGER, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(vehicle_id) REFERENCES vehicles (id), 
	FOREIGN KEY(created_by) REFERENCES users (id)
);
CREATE TABLE tire_records (
	id INTEGER NOT NULL, 
	record_date DATE NOT NULL, 
	vehicle_id INTEGER NOT NULL, 
	quarter VARCHAR, 
	tire_count INTEGER, 
	position VARCHAR, 
	unit_price FLOAT, 
	total_cost FLOAT, 
	supplier VARCHAR, 
	payment_status VARCHAR, 
	notes TEXT, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(vehicle_id) REFERENCES vehicles (id)
);
CREATE TABLE tarp_records (
	id INTEGER NOT NULL, 
	record_date DATE NOT NULL, 
	vehicle_id INTEGER, 
	description VARCHAR NOT NULL, 
	supplier VARCHAR, 
	invoice_number VARCHAR, 
	total_cost FLOAT, 
	payment_status VARCHAR, 
	notes TEXT, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(vehicle_id) REFERENCES vehicles (id)
);
CREATE TABLE trips (
	id INTEGER NOT NULL, 
	trip_date DATE NOT NULL, 
	trip_code VARCHAR, 
	vehicle_id INTEGER, 
	barge_id INTEGER, 
	driver_id INTEGER, 
	customer_name VARCHAR NOT NULL, 
	cargo_type VARCHAR, 
	origin VARCHAR NOT NULL, 
	destination VARCHAR NOT NULL, 
	num_trips INTEGER, 
	weight_tons FLOAT, 
	volume_m3 FLOAT, 
	unit_price FLOAT, 
	total_amount FLOAT, 
	payment_status VARCHAR, 
	notes TEXT, 
	created_by INTEGER, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(vehicle_id) REFERENCES vehicles (id), 
	FOREIGN KEY(barge_id) REFERENCES barges (id), 
	FOREIGN KEY(driver_id) REFERENCES drivers (id), 
	FOREIGN KEY(created_by) REFERENCES users (id)
);
CREATE TABLE weighbridge_trips (
	id INTEGER NOT NULL, 
	trip_order INTEGER, 
	plate_number VARCHAR NOT NULL, 
	trip_type VARCHAR, 
	date_receive VARCHAR, 
	date_delivery VARCHAR, 
	origin VARCHAR, 
	destination VARCHAR, 
	commodity VARCHAR, 
	weight_receive_kg FLOAT, 
	weight_delivery_kg FLOAT, 
	weight_loss_kg FLOAT, 
	weight_loss_pct FLOAT, 
	unit_price FLOAT, 
	amount_by_ton FLOAT, 
	amount_by_trip FLOAT, 
	cost_toll FLOAT, 
	cost_load FLOAT, 
	cost_unload FLOAT, 
	cost_parking FLOAT, 
	cost_tip FLOAT, 
	cost_other FLOAT, 
	cost_station FLOAT, 
	total_cost FLOAT, 
	cost_driver_reported FLOAT, 
	cost_difference FLOAT, 
	notes TEXT, 
	num_trips INTEGER, 
	driver_name VARCHAR, 
	source_images_json TEXT, 
	created_at DATETIME, exchange_ticket_no TEXT, is_office_exchanged BOOLEAN DEFAULT 0, driver_weight_reported REAL, weight_check_note TEXT, vehicle_category VARCHAR DEFAULT "Xe Ben", cost_load_origin FLOAT DEFAULT 0.0, cost_gate_origin FLOAT DEFAULT 0.0, cost_tarp_origin FLOAT DEFAULT 0.0, cost_unload_dest FLOAT DEFAULT 0.0, cost_parking_dest FLOAT DEFAULT 0.0, cost_tarp_dest FLOAT DEFAULT 0.0, uncertain_fields TEXT, is_uncertain BOOLEAN DEFAULT 0, 
	PRIMARY KEY (id)
);
CREATE TABLE vehicle_cost_items (
	id INTEGER NOT NULL, 
	plate_number VARCHAR NOT NULL, 
	driver_name VARCHAR, 
	cost_date VARCHAR, 
	cost_type VARCHAR NOT NULL, 
	description TEXT, 
	liters FLOAT, 
	unit_price FLOAT, 
	amount FLOAT, 
	odo_km FLOAT, 
	source_image VARCHAR, 
	raw_ocr_snippet TEXT, 
	is_verified BOOLEAN, 
	created_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE zalo_processed_files (
	id INTEGER NOT NULL, 
	file_path VARCHAR NOT NULL, 
	file_name VARCHAR NOT NULL, 
	file_size INTEGER, 
	file_mtime FLOAT, 
	detected_category VARCHAR, 
	plate_number VARCHAR, 
	trip_id INTEGER, 
	cost_item_id INTEGER, 
	status VARCHAR, 
	processed_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE system_settings (
	"key" VARCHAR NOT NULL, 
	value TEXT, 
	updated_at DATETIME, 
	PRIMARY KEY ("key")
);
CREATE TABLE salan_cong_ty (
        ma TEXT PRIMARY KEY,
        ten TEXT NOT NULL,
        mst TEXT
    );
CREATE TABLE salan_doi_tac (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        ma TEXT UNIQUE,
        ten TEXT NOT NULL,
        so_dien_thoai TEXT,
        so_tai_khoan TEXT,
        ngan_hang TEXT,
        mst TEXT,
        ghi_chu TEXT
    );
CREATE TABLE salan_phuong_tien (
        ma TEXT PRIMARY KEY,
        loai_phuong_tien TEXT NOT NULL DEFAULT 'sa_lan',
        phan_loai_sa_lan TEXT,
        so_huu TEXT DEFAULT 'doi_tac',
        doi_tac_id INTEGER,
        han_dang_kiem TEXT,
        han_bao_hiem TEXT,
        so_hop_dong TEXT,
        so_chuyen_truoc_so INTEGER DEFAULT 0,
        FOREIGN KEY (doi_tac_id) REFERENCES salan_doi_tac(id)
    );
CREATE TABLE salan_chu_hang (
        ma TEXT PRIMARY KEY,
        ten_chuan TEXT NOT NULL,
        ten_goi_khac TEXT,
        mst TEXT,
        nhom_chu_hang TEXT,
        hh_cho_phep_pct REAL DEFAULT 0.0010,
        ngay_cho_phep_nhan_giao INTEGER DEFAULT 2,
        don_gia_neo_thu INTEGER DEFAULT 4000,
        so_ngay_neo_cho_phep_thu INTEGER DEFAULT 2
    );
CREATE TABLE salan_dia_diem (
        ma TEXT PRIMARY KEY,
        ten TEXT NOT NULL,
        vai_tro TEXT,
        tinh TEXT
    );
CREATE TABLE salan_loai_hang (
        ma TEXT PRIMARY KEY,
        ten TEXT NOT NULL
    );
CREATE TABLE salan_chuyen (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        cong_ty TEXT NOT NULL DEFAULT 'TP',
        loai_phuong_tien TEXT NOT NULL DEFAULT 'sa_lan',
        ma_chuyen TEXT UNIQUE NOT NULL,
        so_thu_tu INTEGER NOT NULL,
        phuong_tien_ma TEXT NOT NULL,
        chu_hang_ma TEXT NOT NULL,
        loai_hang_ma TEXT,
        so_lo_tau TEXT,
        ghi_chu TEXT,
        nguoi_nhap TEXT NOT NULL DEFAULT 'Alex',
        thoi_diem_nhap TEXT,
        trang_thai TEXT NOT NULL DEFAULT 'dang_chay',
        
        ngay_nhan TEXT NOT NULL,
        noi_nhan_ma TEXT NOT NULL,
        kl_nhan_kg INTEGER NOT NULL,
        
        ngay_giao TEXT,
        nha_may_giao_ma TEXT,
        kl_giao_kg INTEGER DEFAULT 0,
        
        don_gia_cuoc INTEGER DEFAULT 0,
        vat_pct REAL DEFAULT 0,
        
        co_tinh_neo INTEGER DEFAULT 0,
        don_gia_neo INTEGER DEFAULT 3000,
        ngay_cho_phep INTEGER DEFAULT 2,
        
        ho_tro INTEGER DEFAULT 0,
        ghi_chu_ho_tro TEXT,
        co_phun_trung INTEGER DEFAULT 0,
        don_gia_phun_trung INTEGER DEFAULT 3000,
        
        hh_cho_phep_pct REAL DEFAULT 0.0010,
        gia_boi_thuong INTEGER DEFAULT 0,
        co_thuong INTEGER DEFAULT 0,
        don_gia_thuong INTEGER DEFAULT 0,
        
        so_bang_ke TEXT,
        so_hoa_don_dau_vao TEXT,
        da_tra_tien INTEGER DEFAULT 0,
        ngay_thanh_toan TEXT,
        khoa_so INTEGER DEFAULT 0,
        da_huy INTEGER DEFAULT 0,
        ly_do_huy TEXT,
        
        -- Phía thu chủ hàng
        hinh_thuc_thu TEXT DEFAULT 'theo_tan',
        don_gia_thu INTEGER DEFAULT 0,
        tien_tron_lo INTEGER DEFAULT 0,
        vat_pct_thu REAL DEFAULT 0.08,
        xong_trung_thu INTEGER DEFAULT 0,
        chu_hang_ho_tro INTEGER DEFAULT 0,
        giam_tru INTEGER DEFAULT 0,
        ly_do_giam_tru TEXT,
        boi_thuong_chu_hang INTEGER DEFAULT 0,
        so_ngay_neo_cho_phep_thu INTEGER DEFAULT 2,
        don_gia_neo_thu INTEGER DEFAULT 4000
    );
CREATE TABLE salan_do_dau (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        chuyen_id INTEGER NOT NULL,
        ngay TEXT NOT NULL,
        noi_do_ma TEXT,
        so_lit REAL NOT NULL DEFAULT 0,
        gia_dau INTEGER NOT NULL DEFAULT 0,
        tien_dau INTEGER NOT NULL DEFAULT 0,
        anh_phieu TEXT,
        ghi_chu TEXT,
        FOREIGN KEY (chuyen_id) REFERENCES salan_chuyen(id) ON DELETE CASCADE
    );
CREATE TABLE salan_ung_phi (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        chuyen_id INTEGER NOT NULL,
        ngay TEXT NOT NULL,
        so_tien INTEGER NOT NULL DEFAULT 0,
        noi_dung TEXT,
        anh_phieu TEXT,
        FOREIGN KEY (chuyen_id) REFERENCES salan_chuyen(id) ON DELETE CASCADE
    );
CREATE TABLE salan_thanh_toan (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        so_phieu TEXT UNIQUE NOT NULL,
        ngay TEXT NOT NULL,
        cong_ty TEXT NOT NULL,
        doi_tac_id INTEGER,
        phuong_tien_ma TEXT,
        so_tien INTEGER NOT NULL,
        nguoi_duyet TEXT,
        ghi_chu TEXT
    );
CREATE TABLE salan_thanh_toan_chuyen (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        thanh_toan_id INTEGER NOT NULL,
        chuyen_id INTEGER NOT NULL,
        so_tien_phan_bo INTEGER NOT NULL,
        FOREIGN KEY (thanh_toan_id) REFERENCES salan_thanh_toan(id) ON DELETE CASCADE,
        FOREIGN KEY (chuyen_id) REFERENCES salan_chuyen(id)
    );
CREATE TABLE salan_nhat_ky_sua (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        bang TEXT NOT NULL,
        ban_ghi_id TEXT NOT NULL,
        hanh_dong TEXT NOT NULL,
        cot TEXT,
        gia_tri_cu TEXT,
        gia_tri_moi TEXT,
        tai_khoan TEXT,
        ly_do TEXT,
        thoi_diem TEXT NOT NULL
    );
CREATE UNIQUE INDEX ix_users_username ON users (username);
CREATE INDEX ix_users_id ON users (id);
CREATE INDEX ix_vehicles_id ON vehicles (id);
CREATE UNIQUE INDEX ix_vehicles_plate_number ON vehicles (plate_number);
CREATE INDEX ix_barges_id ON barges (id);
CREATE UNIQUE INDEX ix_barges_name ON barges (name);
CREATE INDEX ix_drivers_id ON drivers (id);
CREATE INDEX ix_fuel_records_id ON fuel_records (id);
CREATE INDEX ix_tire_records_id ON tire_records (id);
CREATE INDEX ix_tarp_records_id ON tarp_records (id);
CREATE UNIQUE INDEX ix_trips_trip_code ON trips (trip_code);
CREATE INDEX ix_trips_id ON trips (id);
CREATE INDEX ix_weighbridge_trips_id ON weighbridge_trips (id);
CREATE INDEX ix_weighbridge_trips_plate_number ON weighbridge_trips (plate_number);
CREATE INDEX ix_vehicle_cost_items_cost_type ON vehicle_cost_items (cost_type);
CREATE INDEX ix_vehicle_cost_items_id ON vehicle_cost_items (id);
CREATE INDEX ix_vehicle_cost_items_plate_number ON vehicle_cost_items (plate_number);
CREATE UNIQUE INDEX ix_zalo_processed_files_file_path ON zalo_processed_files (file_path);
CREATE INDEX ix_zalo_processed_files_id ON zalo_processed_files (id);
CREATE INDEX ix_system_settings_key ON system_settings ("key");
COMMIT;
